package com.kagafei.g510aicafe;
import android.app.*;import android.os.*;import android.graphics.Color;import android.media.*;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{
 static class Item{String c,n;int p;Item(String c,String n,int p){this.c=c;this.n=n;this.p=p;}}
 final Map<String,List<Item>> menu=new LinkedHashMap<>();final LinkedHashMap<String,Integer> basket=new LinkedHashMap<>();final Map<String,Item> byName=new HashMap<>();GridLayout grid;TextView chat,cart,total,state;EditText input;ToneGenerator tone=new ToneGenerator(AudioManager.STREAM_MUSIC,65);
 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);grid=findViewById(R.id.menuGrid);chat=findViewById(R.id.chat);cart=findViewById(R.id.cart);total=findViewById(R.id.total);state=findViewById(R.id.avatarState);input=findViewById(R.id.input);seed();buildTabs();findViewById(R.id.send).setOnClickListener(v->send());input.setOnEditorActionListener((v,id,e)->{if(id==EditorInfo.IME_ACTION_DONE){send();return true;}return false;});findViewById(R.id.recommend).setOnClickListener(v->ask("おすすめは？"));findViewById(R.id.nonsweet).setOnClickListener(v->ask("甘くない飲み物は？"));findViewById(R.id.help).setOnClickListener(v->ask("注文方法を教えて"));findViewById(R.id.clear).setOnClickListener(v->{basket.clear();refreshCart();say("カートを空にしました。商品をお選びください。");});findViewById(R.id.order).setOnClickListener(v->order());show("ドリンク");}
 void seed(){add("ドリンク","ブレンドコーヒー",380);add("ドリンク","カフェラテ",450);add("ドリンク","紅茶",400);add("ドリンク","抹茶ラテ",500);add("ドリンク","アイスコーヒー",400);add("ドリンク","オレンジジュース",380);add("フード","ホットサンド",580);add("フード","クロワッサン",320);add("フード","ミックスサンド",620);add("フード","ナポリタン",780);add("フード","サラダ",480);add("フード","スープ",420);add("デザート","チーズケーキ",460);add("デザート","プリン",390);add("デザート","ショートケーキ",520);add("デザート","ティラミス",500);add("デザート","アイスクリーム",380);add("デザート","季節のパフェ",780);}
 void add(String c,String n,int p){menu.computeIfAbsent(c,k->new ArrayList<>()).add(new Item(c,n,p));byName.put(n,new Item(c,n,p));}
 void buildTabs(){LinearLayout tabs=findViewById(R.id.tabs);for(String c:menu.keySet()){Button b=new Button(this);b.setText(c);b.setTextSize(16);b.setOnClickListener(v->show(c));tabs.addView(b,new LinearLayout.LayoutParams(0,-1,1));}}
 void show(String c){grid.removeAllViews();for(Item it:menu.get(c)){Button b=new Button(this);b.setText(it.n+"\n"+it.p+"円\n＋ カートに追加");b.setTextSize(16);b.setAllCaps(false);b.setTextColor(Color.rgb(36,27,22));b.setBackgroundColor(Color.WHITE);GridLayout.LayoutParams q=new GridLayout.LayoutParams();q.width=0;q.height=0;q.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);q.rowSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);q.setMargins(5,5,5,5);b.setLayoutParams(q);b.setOnClickListener(v->addToCart(it));grid.addView(b);}}
 void addToCart(Item i){basket.put(i.n,basket.getOrDefault(i.n,0)+1);tone.startTone(ToneGenerator.TONE_PROP_BEEP,90);refreshCart();say(i.n+"をカートに追加しました。ほかの商品もご覧ください。");}
 void refreshCart(){int sum=0;StringBuilder s=new StringBuilder();for(String n:basket.keySet()){Item i=byName.get(n);int q=basket.get(n);sum+=i.p*q;s.append(n).append(" × ").append(q).append("  ").append(i.p*q).append("円\n\n");}cart.setText(basket.isEmpty()?"商品はありません":s);total.setText("合計 "+sum+"円");}
 void send(){String q=input.getText().toString().trim();if(q.isEmpty())return;input.setText("");ask(q);}
 void ask(String q){chat.append("\n\nお客様："+q);String a;if(q.contains("おすすめ"))a="本日のおすすめは、カフェラテとチーズケーキです。画面から商品をお選びください。";else if(q.contains("甘くない")||q.contains("無糖"))a="ブレンドコーヒー、紅茶、アイスコーヒーをご用意しています。";else if(q.contains("注文")||q.contains("方法"))a="右側の写真メニューから商品を選び、カートを確認して注文を確定してください。";else if(q.contains("デザート")||q.contains("甘い"))a="チーズケーキ、プリン、ティラミスが人気です。";else if(q.contains("ラテ")){a="カフェラテは450円です。メニューから追加できます。";}else a="ありがとうございます。おすすめ、甘くない飲み物、注文方法についてご案内できます。";say(a);}
 void say(String a){chat.append("\n\nAI店員："+a);state.setText("AI店員：ご案内中");new Handler().postDelayed(()->state.setText("AI店員：お客様をお待ちしています"),1200);}
 void order(){if(basket.isEmpty()){say("商品が選ばれていません。メニューから商品をお選びください。");return;}int sum=0;for(String n:basket.keySet())sum+=byName.get(n).p*basket.get(n);final int amount=sum;new AlertDialog.Builder(this).setTitle("注文内容の確認").setMessage("合計 "+amount+"円です。注文を確定しますか？").setNegativeButton("戻る",null).setPositiveButton("注文する",(d,w)->{basket.clear();refreshCart();say("ご注文ありがとうございます。商品の準備ができるまでお待ちください。");new AlertDialog.Builder(this).setTitle("注文完了").setMessage("注文番号 A-101\n合計 "+amount+"円").setPositiveButton("OK",null).show();}).show();}
 protected void onDestroy(){tone.release();super.onDestroy();}
}
